Adding debug logging with the following patch on top of commit 9a606fa2af4d6f3bd26a08c74b19cd65761b22cb:
```
diff --git a/src/yb/util/backoff_waiter.h b/src/yb/util/backoff_waiter.h
index f59f160a19..a228f44cde 100644
--- a/src/yb/util/backoff_waiter.h
+++ b/src/yb/util/backoff_waiter.h
@@ -19,6 +19,7 @@
 
 #include "yb/util/monotime.h"
 #include "yb/util/random_util.h"
+#include "yb/util/logging.h"
 
 namespace yb {
 
@@ -43,6 +44,12 @@ class GenericBackoffWaiter {
   }
 
   bool ExpiredAt(TimePoint time) const {
+    LOG(INFO)
+        << "ExpiredAt: "
+        << "time=" << std::chrono::duration_cast<std::chrono::microseconds>(time.time_since_epoch()).count() << " us; "
+        << "deadline_=" << std::chrono::duration_cast<std::chrono::microseconds>(deadline_.time_since_epoch()).count() << " us; "
+        << "time to deadline=" << std::chrono::duration_cast<std::chrono::microseconds>(deadline_ - time).count() << " us; "
+        << "expired: " << (time >= deadline_);
     return time >= deadline_;
   }
 
@@ -54,7 +61,9 @@ class GenericBackoffWaiter {
 
     NextAttempt();
 
-    std::this_thread::sleep_for(DelayForTime(now));
+    auto d = DelayForTime(now);
+    LOG(INFO) << "Waiting for " << d;
+    std::this_thread::sleep_for(d);
     return true;
   }
 
@@ -73,6 +82,16 @@ class GenericBackoffWaiter {
         base_delay_ *
         (attempt_ >= 29 ? std::numeric_limits<int32_t>::max() : 1LL << (attempt_ + 3));
     Duration jitter = std::chrono::milliseconds(RandomUniformInt(0, 50));
+    LOG(INFO) << "DelayForTime: "
+              << "max_wait="
+              << std::chrono::duration_cast<std::chrono::milliseconds>(max_wait) << " ms; "
+              << "attempt_delay="
+              << std::chrono::duration_cast<std::chrono::milliseconds>(attempt_delay) << " ms; "
+              << "jitter="
+              << std::chrono::duration_cast<std::chrono::milliseconds>(jitter) << " ms; "
+              << "result="
+              << std::chrono::duration_cast<std::chrono::milliseconds>(
+                  std::min(attempt_delay + jitter, max_wait)) << " ms";
     return std::min(attempt_delay + jitter, max_wait);
   }
 ```
